const { Client, GatewayIntentBits, SlashCommandBuilder, ActionRowBuilder, ButtonBuilder, ButtonStyle } = require('discord.js');
const { REST } = require('@discordjs/rest');
const { Routes } = require('discord-api-types/v9');
const fs = require('node:fs');
const path = require('node:path');

const client = new Client({ intents: [GatewayIntentBits.Guilds, GatewayIntentBits.GuildMessages, GatewayIntentBits.MessageContent] });
const commands = [];
const commandFiles = fs.readdirSync('./commands').filter(file => file.endsWith('.js'));

client.once('ready', () => {
    console.log(`Logged in as ${client.user.tag}!`);
});

client.on('interactionCreate', async interaction => {
    if (!interaction.isCommand()) return;

    const command = interaction.commandName;

    if (command === 'ban') {
        if (!interaction.member.permissions.has('BanMembers')) return interaction.reply('You do not have permission to use this command.');
        await interaction.guild.members.ban(interaction.options.getUser('user'), { reason: interaction.options.getString('reason') || 'No reason provided.' });
        await interaction.reply({ content: 'User has been banned.', ephemeral: true });
    } else if (command === 'unban') {
        if (!interaction.member.permissions.has('BanMembers')) return interaction.reply('You do not have permission to use this command.');
        const user = interaction.options.getUser('user');
        await interaction.guild.members.unban(user, { reason: interaction.options.getString('reason') || 'No reason provided.' });
        await interaction.reply({ content: 'User has been unbanned.', ephemeral: true });
    } else if (command === 'rules') {
        await interaction.reply({ content: 'Here are the rules of the server.', ephemeral: true });
    } else if (command === 'latency') {
        await interaction.reply({ content: `Ping: ${client.ws.ping}ms` });
