            await interaction.guild.members.addRole(interaction.guild.members.me, role);
            await interaction.reply({ content: 'Added bot to the server.', ephemeral: true });
        } else {
            interaction.reply('I do not have permission to manage roles.');
        }
    } else if (command === 'removebot') {
        if (interaction.guild.members.me.permissions.has('MANAGE_GUILD')) {
            await interaction.guild.members.removeRole(interaction.guild.members.me, 'BotAdmin');
            await interaction.reply({ content: 'Removed bot from the server.', ephemeral: true });
        } else {
            interaction.reply('I do not have permission to manage roles.');
        }
    } else if (command === 'reload') {
        if (interaction.user.id === 'YOUR_BOT_OWNER_ID') {
            const commandFiles = fs.readdirSync('./commands').filter(file => file.endsWith('.js'));
            for (const file of commandFiles) {
                const command = require(`./commands/${file}`);
                client.application.commands.set(command.data, { guildID: interaction.guild.id });
            }
            await interaction.reply({ content: 'Bot has been reloaded.', ephemeral: true });
        } else {
            interaction.reply('You do not have permission to use this command.');
        }
    } else if (command === 'invite') {
        const inviteButton = new ButtonBuilder()
            .setLabel('Add Bot')
            .setStyle(ButtonStyle.Link)
            .setURL(`https://discord.com/api/oauth2/authorize?client_id=${client.user.id}&permissions=8&scope=bot`);

        const row = new ActionRowBuilder().addComponents(inviteButton);

        await interaction.reply({ content: 'Here is the invite link for the bot.', ephemeral: true, components: [row] });
    }
});

// Load commands
async function loadCommands() {
    for (const file of commandFiles) {
        const command = require(`./commands/${file}`);
        commands.push(command.data);
    }
    client.application.commands.set(commands);
}

